import os, glob, re
from collections import defaultdict

def load_grids():
    d = os.environ.get('RLM_SESSION_DIR')
    if not d:
        return {}
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

    grids = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in grids and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            grids[k] = [[int(x) for x in r] for r in rows]
    return grids

